const labelByLang:Record<CultureLang,{section:string;current:string;upcoming:string;official:string;verified:string;generic:string;types:Record<CultureTemporaryEventType,string>}>={
  it:{section:'Mostre ed eventi temporanei',current:'In corso',upcoming:'Prossimamente',official:'Fonte ufficiale',verified:'Verificato',generic:'Programmazione temporanea verificata sul sito ufficiale della struttura.',types:{exhibition:'Mostra',installation:'Installazione','special-event':'Evento speciale','special-opening':'Apertura straordinaria'}},
  en:{section:'Temporary exhibitions & events',current:'Now on',upcoming:'Coming soon',official:'Official source',verified:'Checked',generic:'Temporary programme verified on the venue’s official website.',types:{exhibition:'Exhibition',installation:'Installation','special-event':'Special event','special-opening':'Special opening'}},
  de:{section:'Temporäre Ausstellungen & Veranstaltungen',current:'Aktuell',upcoming:'Demnächst',official:'Offizielle Quelle',verified:'Geprüft',generic:'Temporäres Programm auf der offiziellen Website der Einrichtung geprüft.',types:{exhibition:'Ausstellung',installation:'Installation','special-event':'Sonderveranstaltung','special-opening':'Sonderöffnung'}},
  fr:{section:'Expositions & événements temporaires',current:'En cours',upcoming:'Prochainement',official:'Source officielle',verified:'Vérifié',generic:'Programmation temporaire vérifiée sur le site officiel du lieu.',types:{exhibition:'Exposition',installation:'Installation','special-event':'Événement spécial','special-opening':'Ouverture exceptionnelle'}},
  es:{section:'Exposiciones y eventos temporales',current:'En curso',upcoming:'Próximamente',official:'Fuente oficial',verified:'Verificado',generic:'Programación temporal verificada en la web oficial del lugar.',types:{exhibition:'Exposición',installation:'Instalación','special-event':'Evento especial','special-opening':'Apertura especial'}},
  zh:{section:'临时展览与特别活动',current:'正在进行',upcoming:'即将开始',official:'官方来源',verified:'已核查',generic:'临时展览与活动信息已通过场馆官方网站核查。',types:{exhibition:'展览',installation:'装置','special-event':'特别活动','special-opening':'特别开放'}}
};

export function cultureTemporaryLabels(lang:CultureLang){return labelByLang[lang];}

export function cultureTemporaryEventsFor(placeSlug:string,referenceDate=romeToday()){
  return cultureTemporaryEvents
    .filter(e=>e.placeSlug===placeSlug && e.end>=referenceDate)
    .sort((a,b)=>a.start.localeCompare(b.start));
}

export function cultureTemporaryEventStatus(event:CultureTemporaryEvent,referenceDate=romeToday()){
  return event.start<=referenceDate?'current':'upcoming';
}

export function cultureTemporarySummary(event:CultureTemporaryEvent,lang:CultureLang){
  if(event.summaries?.[lang]) return event.summaries[lang]!;
  if(lang==='it') return event.summaryIt;
  const specific=localizedTemporaryEventDetail(event.title,lang);
  if(specific) return specific;
  return lang==='en'? `${event.title} is part of the venue’s current or upcoming temporary programme; dates and details are based on the official source.`
   :lang==='de'? `${event.title} gehört zum aktuellen oder kommenden Sonderprogramm; Termine und Angaben basieren auf der offiziellen Quelle.`
   :lang==='fr'? `${event.title} fait partie de la programmation temporaire actuelle ou à venir ; dates et détails proviennent de la source officielle.`
   :lang==='es'? `${event.title} forma parte de la programación temporal actual o próxima; fechas y detalles proceden de la fuente oficial.`
   : `${event.title} 属于场馆当前或即将推出的临时项目；日期与信息依据官方来源核查。`;
}
